import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.Bb5YUzRP.js";import{_t as i,dt as a,ft as o,gt as s,ht as c,lt as l,mt as u,pt as d,ut as f,vt as p}from"./chunks/assets.BL_qWEMe.js";var m=JSON.parse(`{"title":"Images","description":"","frontmatter":{},"headers":[],"relativePath":"product-config/images.md","filePath":"product-config/images.md"}`),h={name:`product-config/images.md`},g=p+` 1x, `+i+` 2x`,_=s+` 1x, `+c+` 2x`,v=u+` 1x, `+d+` 2x`,y=o+` 1x, `+a+` 2x`,b=f+` 1x, `+l+` 2x`;function x(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to “Images”">​</a></h1><p>In this section, you can configure the images that are displayed in the designer.</p><p><img src="/webp/product-images.jpg-90-1791641243327.webp" srcset="`+g+`" alt="Product images" title="" width="1684" height="760" loading="lazy" style="width:842px;"></p><h2 id="base-image" tabindex="-1">Base image <a class="header-anchor" href="#base-image" aria-label="Permalink to “Base image”">​</a></h2><p>This is the image that will be displayed in the designer interface. You can configure a base image for each side and for each combination image.</p><p><img src="/webp/combination-images.png-90-1791641243283.webp" srcset="`+_+`" alt="Combination images" title="" width="1700" height="1826" loading="lazy" style="width:850px;"></p><h2 id="mask-image" tabindex="-1">Mask image <a class="header-anchor" href="#mask-image" aria-label="Permalink to “Mask image”">​</a></h2><p>You can configure a mask image for each base image.<br> The role of the mask image is to cover the design excess and limit the customization to the product area.</p><p>The mask image is a <code>PNG</code> or <code>SVG</code> image with a transparent area. This transparent area defines the design area.</p><p>Here&#39;s an example of a base image and a mask image:</p><ul><li>Base image</li></ul><p><img src="/webp/t-shirt.png-90-1791641243347.webp" srcset="`+v+`" alt="T shirt" title="" width="992" height="1112" loading="lazy" style="width:496px;"></p><ul><li>Mask image</li></ul><p><img src="/webp/t-shirt-mask.png-90-1791641243346.webp" srcset="`+y+`" alt="T shirt mask" title="" width="992" height="1112" loading="lazy" style="width:496px;"></p><p>Notice the transparent area in the mask image. When this image is applied on top of the design, then only the design that is in the product area will be visible.</p><ul><li>Full example</li></ul><p><img src="/webp/mask-example.jpg-90-1791641243317.webp" srcset="`+b+`" alt="Mask example" title="" width="992" height="1112" loading="lazy" style="width:496px;"></p><p>Only the part of the design that is under the transparency is visible.</p><h2 id="production-canvas" tabindex="-1">Production canvas <a class="header-anchor" href="#production-canvas" aria-label="Permalink to “Production canvas”">​</a></h2><p>The production canvas is only included in the final SVG. It&#39;s useful when you want to use a large background image for production but only show a smaller image in the product page to ensure a faster page load.</p><h2 id="production-mask" tabindex="-1">Production mask <a class="header-anchor" href="#production-mask" aria-label="Permalink to “Production mask”">​</a></h2><p>The production mask follows the same principles are the <a href="#mask-image">mask image</a> but is only included in the production SVG.</p>`,22)]])}var S=e(h,[[`render`,x]]);export{m as __pageData,S as default};